entries[21217] = { ["name"] = "Weisenfisch Supreme", ["text"] = "Benötigt Stufe 30\nBenutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 8 Mana.\nVerkaufspreis:" }
entries[21218] = { ["name"] = "Blauer Qirajiresonanzkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier kann nur im Tempel von Ahn'Qiraj beschworen werden.\nStößt ein Hochfrequenzsignal aus, das eine Qirajipanzerdrohne dazu zwingt, sich aus dem Boden unter dem Tempel von Ahn'Qiraj an die Oberfläche zu graben. Der Silithide gehorcht seinem Beschwörer und kann innerhalb des Tempels von Ahn'Qiraj als Reittier benutzt werden. Jegliche feindseligen Handlungen gegen den Reiter zwingen die Qirajipanzerdrohne, sich wieder einzugraben." }
entries[21219] = { ["name"] = "Rezept: Weisenfisch Supreme", ["text"] = "Benötigt Kochkunst (175)\nBenutzen: Lehrt Euch, wie man Weisenfisch Surpreme zubereitet.\nVerkaufspreis:\nWeisenfisch Supreme\nBenötigt Stufe 30\nBenutzen: Stellt im Verlauf von 21 Sek. 840.0 Gesundheit und 1260 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und regeneriert 15 Min. lang alle 5 Sekunden 8 Mana.\nVerkaufspreis:\nBenötigt Roher großer Weisenfisch" }
